// === Tab: mySketch.js ===
// 音效
let mySound;
let amplitude;

let seed, mySize;
let angle_c;
let colors = [];
let colors7 = "fefefe-292929-ffffff-222222-202020".split("-").map((a) => "#" + a);
var color_setup1, color_setup2;
let color_bg;
let branch;
let colList = [];
let mic;

function preload() {
	// 加载音频文件
	soundFormats('mp3', 'ogg');
	mySound = loadSound('https://openprocessing.org/sketch/1941217/files/996.mp3');
}

function setup() {

	// 设置画布尺寸
	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize);

	// 初始化种子、角度和背景颜色
	seed = int(random(1000));
	colorMode(HSB, 360, 100, 100, 100);
	color_bg = "#202020";
	background(color_bg);
	background(0);
	angle_c = 0;

	// 随机选择分支数量
	branch = int(random(4, 20));

	// 设置音量和播放音频
	mySound.setVolume(0.5);
	mySound.play();

	// 创建振幅对象，并将音频输入连接到振幅对象 实现音乐音量的获取
	amplitude = new p5.Amplitude();
	amplitude.setInput(mySound);

	// 创建麦克风对象并启动
	mic = new p5.AudioIn();
	mic.start();

	// 设置颜色和颜色列表
	color_setup1 = colors7;
	colList = ["#A0271C", "#D33C33", "#F57951", "#F7A35C", "#F6E056", "#E2C780", "#1D464C", "#50747A", "#4A91A7", "#1A3E78", "#504979", "#514E55", "#E0DED2"];
}

function draw() {

	// 计算麦克风声音以及音乐声音的总和
	let vol = amplitude.getLevel() * 0.8 + mic.getLevel();

	// 随机种子
	randomSeed(seed);

	// 设置阴影效果
	drawingContext.shadowColor = str(random(color_setup1)) + "00";
	drawingContext.shadowOffsetX = 0;
	drawingContext.shadowOffsetY = 0;
	drawingContext.shadowBlur = 0;

	// 平移坐标系到画布中心
	translate(width / 2, height / 2);

	// 根据音频振幅调整旋转角度
	let vol_m = map(vol, 0, 1, 1, 50);
	rotate(angle_c * random(-vol_m, vol_m) + frameCount * 0.01);

	// 根据帧数和分支数量调整分支数目和旋转角度
	if (frameCount % 200 == 0 && branch < 200) {
		branch += vol_m;
		angle_c += TAU / 360;
	} else if (branch >= 200) {
		branch = 4;
		frameCount = 0;
	}

	// 绘制分支
	for (let num = 0; num < 3; num++) {
		for (let b = 0; b < 16; b++) {
			// 根据音量变化长度
			let leng = map(vol, 0, 1, 50, width / 2) + random(width * 0.15);
			// 使用极坐标方程计算线段顶点位置

			let angle1 = map(b, 0, 16, 0, TWO_PI);
			let angle2 = map(b + 1, 0, 16, 0, TWO_PI) + iteration(0.1, 0.25);
			let x1 = cos(angle1) * leng;
			let y1 = sin(angle1) * leng;
			let x2 = cos(angle2) * leng;
			let y2 = sin(angle2) * leng;
			// 设置阴影效果
			drawingContext.shadowColor = random(color_setup1);
			drawingContext.shadowOffsetX = 1;
			drawingContext.shadowOffsetY = 1;
			drawingContext.shadowBlur = 0;

			// 设置线条样式和颜色
			strokeWeight(random(1));
			stroke(colList[int(random(colList.length))]);

			// 绘制线段
			line(x1, y1, x2, y2);
		}
	}
}

function circleForm(x, y, d) {
	// 计算分支角度
	let ang = TAU / branch;
	let angles = [];
	for (let i = 0; i < branch; i++) {
		angles.push(ang * (i + iteration(0.1, 0.25)));
	}

	// 绘制圆形
	for (let i = 0; i < branch; i++) {
		let ang1 = angles[i];
		let ang2 = angles[(i + int(random(6))) % angles.length];
		let dd = d * iteration(0.1, 1);

		noFill();

		// 设置阴影效果
		drawingContext.shadowColor = random(color_setup1);
		drawingContext.shadowOffsetX = 1;
		drawingContext.shadowOffsetY = 1;
		drawingContext.shadowBlur = 0;

		// 设置线条样式和颜色
		stroke(colors[random([0, 1, 2, 3, 4])]);
		strokeWeight(random(1));

		// 绘制弧线
		arc(x, y, dd, dd, ang1, ang2);
	}
}

function iteration(s, e) {
	// 计算迭代值
	let t = random(10, 100);
	let v = random(0.001, 0.01);
	return map(cos(t + frameCount * v), -1, 1, s, e);
}

function keyTyped() {
	// 按下"s"或"S"键时保存画布为PNG图像
	if (key === "s" || key === "S") {
		saveCanvas("0504_NoisePlanet_Spiral(996)_2022", "png");
	}
}

